use five_leads_study::three_leads::{Divisor,Jacobian,Ring,SignedGraph};
use serde_json::{json,Value};use std::collections::{HashMap,HashSet};
#[derive(Clone)] struct Equation{u:usize,su:i8,v:usize,sv:i8,a:u64,b:u64}
fn mul(a:u64,b:u64,r:u64)->u64{(a as u128*b as u128%r as u128)as u64}
fn sub(a:u64,b:u64,r:u64)->u64{((a as u128+r as u128-b as u128)%r as u128)as u64}
fn pow(mut a:u64,mut e:u64,r:u64)->u64{let mut z=1;while e>0{if e&1!=0{z=mul(z,a,r)}a=mul(a,a,r);e>>=1}z}
fn dense(es:&[Equation],n:usize,r:u64)->Option<u64>{let mut rows=vec![];for e in es{let mut row=vec![0;n+1];for(i,s)in[(e.u,e.su),(e.v,e.sv)]{if i!=0{row[i-1]=(row[i-1]+if s==1{1}else{r-1})%r}}row[n-1]=sub(0,e.b,r);row[n]=e.a;rows.push(row)}let mut pivot=0;for col in 0..n{let Some(i)=(pivot..rows.len()).find(|&i|rows[i][col]!=0)else{continue};rows.swap(pivot,i);let inv=pow(rows[pivot][col],r-2,r);for z in &mut rows[pivot]{*z=mul(*z,inv,r)}let pr=rows[pivot].clone();for(i,row)in rows.iter_mut().enumerate(){if i!=pivot{let c=row[col];for j in 0..=n{row[j]=sub(row[j],mul(c,pr[j],r),r)}}}pivot+=1;}
let mut answer=None;for row in rows{if row[..n-1].iter().all(|&x|x==0){if row[n-1]==0{assert_eq!(row[n],0,"inconsistent dense equations")}else{let k=mul(row[n],pow(row[n-1],r-2,r),r);if let Some(old)=answer{assert_eq!(old,k)}answer=Some(k)}}}answer}
pub struct Adapter{ring:Ring,graph:SignedGraph,nodes:HashMap<u64,usize>,seen:HashSet<Divisor>,eqs:Vec<Equation>}
impl Adapter{pub fn new(r:u64)->Self{let ring=Ring::new(r);Self{graph:SignedGraph::new(ring.clone()),ring,nodes:HashMap::new(),seen:HashSet::new(),eqs:vec![]}}
pub fn consume(&mut self,j:&Jacobian,d:Option<Divisor>,a:u64,b:u64)->Value{let before=j.f.counts();let Some(d)=d else{return json!({"status":"recovery_failed","answer":null})};if d.degree!=2{return json!({"status":"degree_gate_skip","answer":null})}let p=j.f.p;let disc=j.f.sub(j.f.sq(d.u[1]),j.f.mul(4,d.u[0]));let Some(root)=j.f.sqrt(disc)else{return json!({"status":"nonsplit","answer":null,"field":j.f.counts()-before})};let xs=[j.f.mul(j.f.sub(root,d.u[1]),p.div_ceil(2)),j.f.mul(j.f.sub(j.f.neg(root),d.u[1]),p.div_ceil(2))];if xs[0]==xs[1]{return json!({"status":"repeated_root","answer":null,"field":j.f.counts()-before})}if !self.seen.insert(d.min(j.neg(d))){return json!({"status":"duplicate","answer":null,"field":j.f.counts()-before})}let ys=xs.map(|x|j.f.add(d.v[0],j.f.mul(d.v[1],x)));let signs=ys.map(|y|if y<=p/2{1}else{-1});let ns=xs.map(|x|*self.nodes.entry(x).or_insert_with(||self.graph.node()));let processing=j.f.counts()-before;let rb=self.ring.counts.get();let gb=self.graph.operations;let cb=self.graph.cycles;let nb=self.graph.negative_cycles;let zb=self.graph.zero_coefficient;let answer=self.graph.edge(ns[0],signs[0],ns[1],signs[1],a,b);self.eqs.push(Equation{u:ns[0],su:signs[0],v:ns[1],sv:signs[1],a,b});let reference=dense(&self.eqs,self.graph.nodes(),self.ring.r);assert_eq!(answer,reference);
let before=j.f.counts();let factors=[0,1].map(|i|Divisor{degree:1,u:[if xs[i]==0{0}else{p-xs[i]},1,0],v:[ys[i],0]});assert!(factors.iter().all(|&v|j.valid(v)));assert_eq!(j.add(factors[0],factors[1]),d);json!({"status":"inserted","answer":answer,"dense_answer":reference,"equation":{"nodes":ns,"signs":signs,"a":a,"b":b},"prefix_equations":self.eqs.len(),"nodes":self.graph.nodes(),"cycles_delta":self.graph.cycles-cb,"negative_cycles_delta":self.graph.negative_cycles-nb,"zero_coefficient_delta":self.graph.zero_coefficient-zb,"graph_operations":self.graph.operations-gb,"ring_before":rb,"ring_after":self.ring.counts.get(),"processing_field":processing,"factor_verification_field":j.f.counts()-before,"factor_sum_verified":true})}}
pub fn controls()->Value{let mut out=vec![];for(name,edges,stop)in[("positive_cycle",vec![(1,1,2,-1,91,0),(2,1,3,-1,91,0),(1,1,3,-1,74,1)],3),("negative_anchor",vec![(1,1,1,1,20,0),(1,1,0,1,3,1)],2),("zero_then_positive",vec![(1,1,2,-1,91,0),(1,1,2,-1,91,0),(2,1,3,-1,91,0),(1,1,3,-1,74,1)],4)]{let ring=Ring::new(101);let mut graph=SignedGraph::new(ring.clone());for _ in 0..3{graph.node();}let mut eqs=vec![];let mut rows=vec![];let mut stopped=None;for(u,su,v,sv,a,b)in edges.into_iter().chain(std::iter::once((0,1,0,1,1,0))){let ans=graph.edge(u,su,v,sv,a,b);eqs.push(Equation{u,su,v,sv,a,b});let reference=dense(&eqs,graph.nodes(),101);assert_eq!(ans,reference);rows.push(json!({"equation":[u as i64,su as i64,v as i64,sv as i64,a as i64,b as i64],"answer":ans,"dense_answer":reference}));if let Some(k)=ans{assert_eq!(k,7);stopped=Some(eqs.len());break}}assert_eq!(stopped,Some(stop));out.push(json!({"name":name,"rows":rows,"stop_prefix":stopped,"ring":ring.counts.get(),"graph_operations":graph.operations,"cycles":graph.cycles,"negative_cycles":graph.negative_cycles,"zero_coefficient":graph.zero_coefficient,"scope":"synthetic signed-equation control"}));}json!(out)}
